3. C# Programming Language
➢ Lists:
 static void Main(string[] args)
 {    List<int> ls = new List<int>();
      int x; int i = 0;
      do{
          i++; Console.WriteLine("nhap gia trịthu {0}:", i);
          x = Convert.ToInt16(Console.ReadLine());
          ls.Add(x);
      } while (x != 0);
      foreach (int a in ls) //in danh sách
      { Console.Write("{0}    ", a);   }
      Console.WriteLine("nhap gia trị cần xóa:");
      x = Convert.ToInt16(Console.ReadLine());
      if (ls.Contains(x)){
          ls.Remove(x);
          foreach (int a in ls) { Console.Write("{0}   ", a); }
      }else
          Console.WriteLine("không có phần tử trong danh sách");
 }                                                                 60

