➢ throw …
public static double Divide(double x, double y)
{
    if (y == 0){
      // Khởi tạo ngoại lệ, tham số là thông báo lỗi
      Exception e = new Exception("Số chia không được bằng 0");
     // phát sinh ngoại lệ, code phía sau throw được thực thi
      throw e;
    }
    return x / y;
}
static void Main(string[] args)
{
    try{
